-- Wedding function decks: Sangeet and Mehndi colours and outfit styles (destination "wedding"). Colour cards use swatch
-- images drawn for this app (web/public/cards/wedding). Outfit-style cards link to image searches instead of hosting photos:
-- outfit photos on Wikimedia Commons are scarce and mostly traditional, and other sources are not ours to copy.
insert into swipe_decks (key, label, description, sort_order, destination) values ($q$wedding-sangeet-colours$q$, $q$Sangeet: colours$q$, $q$Colour palettes and how bride and groom combine them. Theme: Glitz & Glamour, indo-western.$q$, 10, 'wedding');
